package ch.motherheart.archunit.fixtures.good.library.member.persistence;

import ch.motherheart.archunit.fixtures.good.library.member.dto.MemberListItem;
import jakarta.persistence.EntityManager;
import java.util.List;
import java.util.Optional;

/**
 * Simulates code generated by hibernate-processor: validated at build time, so it may use query strings.
 * Like a {@code CrudRepository} implementation it also offers {@code findAll()}: tolerated, as long as nobody calls it.
 */
public class MemberRepository_ implements MemberRepository {
    private EntityManager entityManager;

    @Override
    public Optional<Member> findById(Long id) {
        return Optional.ofNullable(entityManager.find(Member.class, id));
    }

    @Override
    public Member insert(Member member) {
        entityManager.persist(member);
        return member;
    }

    @Override
    public List<MemberListItem> list() {
        return entityManager.createQuery("select new MemberListItem(c.id, c.name) from Member c", MemberListItem.class)
                .getResultList();
    }

    @Override
    public long countById(Long id) {
        return 0;
    }

    public List<Member> findAll() {
        return entityManager.createQuery("from Member", Member.class).getResultList();
    }
}
